/**
 * Plugin Name: Paid Memberships Pro - Post Affiliate Pro Integration Add On
 * Plugin URI: https://www.paidmembershipspro.com/add-ons/pmpro-post-affiliate-pro-integration/
 * Description: Process an affiliate via Post Affiliate Pro after a PMPro checkout.
 * Version: 0.4
 * Author: Stranger Studios
 * Author URI: https://www.strangerstudios.com
 *		 
 * Paid Memberships Pro (https://www.paidmembershipspro.com) must be installed and activated. 
 * You will need a Post Affiliate Pro account.
*/
/*
 * Post Affiliate Pro settings.
 *
 * Do not edit this file to enter your settings. WordPress replaces this entire
 * file every time the Add On is updated, so settings entered here are erased on
 * update and affiliate tracking silently stops working.
 *
 * Instead, add these constants to your site's wp-config.php file, above the line
 * that reads "That's all, stop editing!":
 *
 *     define( 'URL_TO_PAP', 'https://youraccount.postaffiliatepro.com/' );
 *     define( 'PAP_LOGIN', 'you@example.com' );
 *     define( 'PAP_PASS', 'your-pap-password' );
 *
 * PAP_ACCOUNT only needs to be defined if your Post Affiliate Pro account ID is
 * something other than "default1".
 *
 * wp-config.php loads before plugins, so the constants defined there take
 * priority and the placeholder values below are skipped.
 */
if ( ! defined( 'URL_TO_PAP' ) ) {
	define( 'URL_TO_PAP', 'https://{account}.postaffiliatepro.com/' );
}
if ( ! defined( 'PAP_LOGIN' ) ) {
	define( 'PAP_LOGIN', '{email}' );
}
if ( ! defined( 'PAP_PASS' ) ) {
	define( 'PAP_PASS', '{pass}' );
}
if ( ! defined( 'PAP_ACCOUNT' ) ) {
	define( 'PAP_ACCOUNT', 'default1' );
}

//login to API
function pap_login()
{
	require_once(dirname(__FILE__) . "/lib/PapApi.class.php");
	$session = new Gpf_Api_Session(URL_TO_PAP . "scripts/server.php");	
	if(!$session->login(PAP_LOGIN, PAP_PASS)) {
		//if admin, show notice. else ignore
		if(current_user_can("manage_options"))
		{
		?>
			<p>ERROR: Can't authenticate with Post Affiliates Pro. Check that your PAP credentials are correct in the PMPro Post Affiliates Pro plugin and that the Post Affiliates Pro API is not experiencing an outage. Response from PAP: <?php echo $session->getMessage();?></p>
		<?php
		}
		else
		{	  
			//shhh... don't let users know
		}
	}
}

//function to save a sale with PAP
function pap_pmpro_track_sale($total, $orderid, $affiliate_code = NULL, $campaign_id = NULL, $channel_id = NULL, $visitor_id = NULL, $level_id = NULL)
{
	pap_login();
	$saleTracker = new Pap_Api_SaleTracker(URL_TO_PAP . 'scripts/sale.php');
	$saleTracker->setAccountId(PAP_ACCOUNT);
	
	if(!empty($visitor_id))
		$saleTracker->setVisitorId($visitor_id);

    $sale1 = $saleTracker->createSale();
    $sale1->setTotalCost($total);
    $sale1->setOrderID($orderid);

    //orders tracked from pmpro_add_order aren't saved yet, so callers should pass the level ID instead of having us look the order up by code
    if(empty($level_id))
    {
        $order = new MemberOrder($orderid);
        $level_id = $order->membership_id;
    }
    $level = pmpro_getLevel($level_id);

    $sale1->setProductID(sanitize_title(empty($level) ? "" : $level->name, "pmpro-level-" . $level_id));
	
	if(!empty($affiliate_code))
		$sale1->setAffiliateID($affiliate_code);
	if(!empty($campaign_id))
		$sale1->setCampaignID($campaign_id);
	if(!empty($channel_id))
		$sale1->setChannelID($channel_id);
	
	try
	{
		$saleTracker->register();
	}
	catch(Exception $e)
	{				
		//die($e->getMessage);
		if(current_user_can("manage_options"))
		{
		?>
			<p>ERROR: <?php echo $e->getMessage();?></p>
		<?php
		}
		else
		{
			//shhhh... don't let normal users know
		}
	}	
}

//get the affiliate info from the visitor's affiliate cookie
function pap_pmpro_get_cookie_affiliate()
{
	if(empty($_COOKIE['pap_pmpro_affiliate']))
		return false;

	$parts = array_pad(explode(",", $_COOKIE['pap_pmpro_affiliate']), 4, "");
	if(empty($parts[0]))
		return false;

	$visitor_id = $parts[3];
	if(empty($visitor_id) && !empty($_COOKIE['PAPVisitorId']))
		$visitor_id = $_COOKIE['PAPVisitorId'];

	return array(
		'affiliate_id' => $parts[0],
		'affiliate_subid' => $parts[1] . "," . $parts[2] . "," . $visitor_id,
	);
}

//track sales after checkout
function pap_pmpro_after_checkout($user_id, $morder = NULL)
{
	//get a fresh copy of the order that was checked out
	if(!empty($morder->id))
	{
		$morder = new MemberOrder($morder->id);
	}
	else
	{
		$morder = new MemberOrder();
		$morder->getLastMemberOrder($user_id);
	}

	if(empty($morder->id) || empty($morder->total))
		return;

	//only track one sale per order
	if(get_pmpro_membership_order_meta($morder->id, 'pap_pmpro_sale_tracked', true))
		return;

	/*
		Use the affiliate cookie if we have one. Otherwise, use the affiliate saved
		to the order when it was added. (e.g. the checkout was completed by a gateway
		webhook, or a returning member checked out without a cookie)
	*/
	$affiliate = pap_pmpro_get_cookie_affiliate();
	if(empty($affiliate) && !empty($morder->affiliate_id))
		$affiliate = array('affiliate_id' => $morder->affiliate_id, 'affiliate_subid' => $morder->affiliate_subid);
	if(empty($affiliate))
		return;

	$parts = array_pad(explode(",", (string)$affiliate['affiliate_subid']), 3, "");

	//api
	pap_pmpro_track_sale($morder->total, $morder->code, $affiliate['affiliate_id'], $parts[0], $parts[1], $parts[2], $morder->membership_id);
	update_pmpro_membership_order_meta($morder->id, 'pap_pmpro_sale_tracked', 1);

	//save affiliate id in order
	if($morder->affiliate_id != $affiliate['affiliate_id'] || $morder->affiliate_subid != $affiliate['affiliate_subid'])
	{
		$morder->affiliate_id = $affiliate['affiliate_id'];
		$morder->affiliate_subid = $affiliate['affiliate_subid'];
		$morder->saveOrder();
	}
}
add_action("pmpro_after_checkout", "pap_pmpro_after_checkout", 10, 2);

//track sales when orders are added
function pap_pmpro_add_order($morder)
{
	global $pap_pmpro_affiliate_id, $pap_pmpro_affiliate_subid, $pap_pmpro_sale_tracked;
	$pap_pmpro_affiliate_id = NULL;
	$pap_pmpro_affiliate_subid = NULL;
	$pap_pmpro_sale_tracked = false;

	if(!empty($morder->total))
	{
		//orders added at checkout are tracked in pap_pmpro_after_checkout once the checkout is complete
		$is_checkout = pmpro_is_checkout();

		//at checkout, the affiliate cookie takes priority
		$affiliate = $is_checkout ? pap_pmpro_get_cookie_affiliate() : false;

		if(empty($affiliate))
		{
			//need to get the last order before this
			$last_order = new MemberOrder();
			$last_order->getLastMemberOrder($morder->user_id);

			if(!empty($last_order->affiliate_id))
				$affiliate = array('affiliate_id' => $last_order->affiliate_id, 'affiliate_subid' => $last_order->affiliate_subid);
		}

		if(!empty($affiliate))
		{
			if(!$is_checkout)
			{
				$parts = array_pad(explode(",", (string)$affiliate['affiliate_subid']), 3, "");

				//api
				pap_pmpro_track_sale($morder->total, $morder->code, $affiliate['affiliate_id'], $parts[0], $parts[1], $parts[2], $morder->membership_id);
				$pap_pmpro_sale_tracked = true;
			}

			//update the affiliate id for this order
			$pap_pmpro_affiliate_id = $affiliate['affiliate_id'];
			$pap_pmpro_affiliate_subid = $affiliate['affiliate_subid'];
		}
	}
}
add_action("pmpro_add_order", "pap_pmpro_add_order");

//save affiliate ids into orders
function pap_pmpro_added_order($morder)
{
	global $pap_pmpro_affiliate_id, $pap_pmpro_affiliate_subid, $pap_pmpro_sale_tracked;

	//remember that we already tracked a sale for this order
	if(!empty($pap_pmpro_sale_tracked))
		update_pmpro_membership_order_meta($morder->id, 'pap_pmpro_sale_tracked', 1);

	if(!empty($pap_pmpro_affiliate_id))
	{
		//use a fresh copy of the order. PMPro casts the affiliate_id of a brand new order object to an integer, which breaks affiliate IDs with letters in them
		$order = new MemberOrder($morder->id);
		$order->affiliate_id = $pap_pmpro_affiliate_id;
		$order->affiliate_subid = $pap_pmpro_affiliate_subid;
		$order->saveOrder();
	}
}
add_action("pmpro_added_order", "pap_pmpro_added_order");

//show affiliate id on orders dashboard page
add_action("pmpro_orders_show_affiliate_ids", "__return_true");

//check for affiliate code
function pap_pmpro_wp_head()
{
	pap_login();
	
    // init session for PAP
    $session = new Gpf_Api_Session(URL_TO_PAP . "scripts/server.php");
    
    // register click
    $clickTracker = new Pap_Api_ClickTracker($session);

    $clickTracker->setAccountId(PAP_ACCOUNT);

    try {  
        $clickTracker->track();
        $clickTracker->saveCookies();                
    } catch (Exception $e) {
    	//stop here
    	
		//die($e->getMessage);
		if(current_user_can("manage_options"))
		{
		?>
			<p>ERROR: <?php echo $e->getMessage();?></p>
		<?php
		}
		else
		{
			//shhhh... don't let normal users know
		}
				
    	return;   	
    }
    
    //save some values from the click tracker for later
	if($clickTracker->getAffiliate())
	{
		$affiliate_id = $clickTracker->getAffiliate()->getValue('refid');
			
		if($clickTracker->getCampaign())
			$campaign_id = $clickTracker->getCampaign()->getValue('campaignid');
		else
			$campaign_id = "";
		
		if($clickTracker->getChannel())
			$channel_id = $clickTracker->getChannel()->getValue('channelid');
		else
			$channel_id = "";
		
		if(!empty($clickTracker->visitorId))
			$visitor_id = $clickTracker->visitorId;
		else
			$visitor_id = "";
		
		$pap_pmpro_affiliate =
				$affiliate_id . "," . $campaign_id . "," . $channel_id . "," . $visitor_id;
			
		//save our cookies	
		$cookielength = 90;
		?>
			<script>
				var today = new Date();
				today.setTime( today.getTime() );
				var expires = <?php echo intval($cookielength); ?> * 1000 * 60 * 60 * 24;
				var expires_date = new Date( today.getTime() + (expires) );
				document.cookie = 'pap_pmpro_affiliate=<?php echo $pap_pmpro_affiliate; ?>;path=/;expires=' + expires_date.toGMTString() + ';';		    
			</script>
		<?php
	}
}
add_action("wp_head", "pap_pmpro_wp_head");

/*
Function to add links to the plugin row meta
*/
function pap_pmpro_plugin_row_meta( $links, $file ) {
	if ( strpos( $file, 'pmpro-post-affiliate-pro.php' ) !== false ) {
		$new_links = array(
			'<a href="' . esc_url('https://www.paidmembershipspro.com/add-ons/pmpro-post-affiliate-pro-integration/')  . '" title="' . esc_attr__( 'View Documentation', 'pmpro-post-affiliate-pro' ) . '">' . esc_html__( 'Docs', 'pmpro-post-affiliate-pro' ) . '</a>',
			'<a href="' . esc_url('https://paidmembershipspro.com/support/') . '" title="' . esc_attr__( 'Visit Customer Support Forum', 'pmpro-post-affiliate-pro' ) . '">' . esc_html__( 'Support', 'pmpro-post-affiliate-pro' ) . '</a>',
		);
		$links = array_merge($links, $new_links);
	}
	return $links;
}
add_filter('plugin_row_meta', 'pap_pmpro_plugin_row_meta', 10, 2);
